fis:MoneyMarketFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
        fis:MutualFund [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestment ; owl:someValuesFrom fis:MoneyMarketInstrument ]
    ) ] .

fis:BondFund a owl:Class ;
    rdfs:label "income fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
        fis:MutualFund [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestment ; owl:someValuesFrom fis:Bond ]
    ) ] .

fis:EquityFund a owl:Class ;
    rdfs:label "stock fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
        fis:MutualFund [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestment ; owl:someValuesFrom fis:Stock ]
    ) ] .

fis:HybridFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
        fis:MutualFund [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestment ; owl:someValuesFrom fis:HybridSecurity ]
    ) ] .

fis:IndexFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
        fis:Fund [ a owl:Restriction ; owl:onProperty fis:hasTrackedIndex ; owl:someValuesFrom fis:PriceIndex ]
